// Package places is optional world knowledge for the generic-v2 comparator:
// which words name the same place. It knows every airport with an IATA code
// (airportsdata, MIT licence; generated by scripts/wordnet/gen_places.py), so
// "BLR", "Bangalore" and "Bengaluru" are one place, and so are "MAA" and
// "Chennai". It is geography, not a model of any task: a hotel, a parcel or a
// rental car is in a city as much as a flight is.
package places

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"strings"
	"sync"
)

//go:embed places.tsv.gz
var raw []byte

var (
	once   sync.Once
	byWord map[string][]string // alias word or code -> codes
)

func load() {
	once.Do(func() {
		byWord = make(map[string][]string, 20000)
		zr, err := gzip.NewReader(bytes.NewReader(raw))
		if err != nil {
			panic("places: embedded table is not gzip: " + err.Error())
		}
		sc := bufio.NewScanner(zr)
		for sc.Scan() {
			code, rest, ok := strings.Cut(sc.Text(), "\t")
			if !ok {
				continue
			}
			byWord[code] = append(byWord[code], code)
			for _, w := range strings.Fields(rest) {
				byWord[w] = append(byWord[w], code)
			}
		}
	})
}

// Same reports whether a and b can name the same place: one is an airport
// code and the other a name of its city, or both are names of one city.
func Same(a, b string) bool {
	if a == b {
		return true
	}
	load()
	ca, cb := byWord[a], byWord[b]
	for _, x := range ca {
		for _, y := range cb {
			if x == y {
				return true
			}
		}
	}
	return false
}
